def algorithm(func, dim, lb, ub, budget, rng):
    x_best = np.array([0.]*dim)
    f_best = func(x_best)

    for i in range(budget):
        x_candidate = lb + (ub - lb) * rng.normal(size=dim)
        f_candidate = func(np.clip(x_candidate, lb, ub))

        if f_candidate < f_best:
            x_best = x_candidate
            f_best = f_candidate

    return np.clip(x_best, lb, ub)
